"""Render Hand Posing on an adult female MPFB hand in a disposable scene.

Use --mpfb-dir to generate the model from an installed MPFB extension, or
--source-blend to reuse a model generated by this script. Run in background
Blender with an isolated user profile. Model assets stay in .cache.
"""

import argparse
import hashlib
import importlib
import json
import math
from pathlib import Path
import sys

import addon_utils
import bpy
from mathutils import Matrix, Quaternion, Vector

project = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(project))
import hand_posing as addon

parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument('--mpfb-dir', type=Path)
parser.add_argument('--source-blend', type=Path)
parser.add_argument('--constraints', type=Path)
parser.add_argument('--skip-render', action='store_true')
parser.add_argument('--thumb-spread-degrees', type=float, default=35.0)
parser.add_argument('--skin-mhmat', type=Path)
arguments = parser.parse_args(sys.argv[sys.argv.index('--') + 1:] if '--' in sys.argv else [])


def load_mpfb():
    if not arguments.mpfb_dir:
        parser.error('--mpfb-dir is required to generate a model or apply its skin')
    extension_root = arguments.mpfb_dir.resolve().parent
    bpy.ops.preferences.extension_repo_add(name='Preview Assets', type='LOCAL',
                                         use_custom_directory=True, custom_directory=str(extension_root))
    repo = next(repo for repo in bpy.context.preferences.extensions.repos
                if Path(repo.directory).resolve() == extension_root)
    mpfb = addon_utils.enable(f'bl_ext.{repo.module}.{arguments.mpfb_dir.name}', default_set=True)
    assert mpfb, 'MPFB could not be enabled'
    return importlib.import_module(mpfb.__name__ + '.services')


services = None
if arguments.source_blend:
    bpy.ops.wm.open_mainfile(filepath=str(arguments.source_blend.resolve()))
else:
    services = load_mpfb()
    assert addon_utils.enable('rigify', default_set=True)
    macros = services.TargetService.get_default_macro_info_dict()
    macros.update(gender=0.0, age=0.5)
    skin = services.HumanService.create_human(macro_detail_dict=macros)
    meta = services.HumanService.add_builtin_rig(skin, 'rigify.human')
    rig = services.RigService.generate_rigify_rig(meta, name='MPFB Preview')
    assert rig, 'Rigify generation failed'
    model = project / '.cache/mpfb-preview-source.blend'
    model.parent.mkdir(parents=True, exist_ok=True)
    bpy.ops.wm.save_as_mainfile(filepath=str(model))

rig = next(obj for obj in bpy.context.scene.objects
           if obj.type == 'ARMATURE' and 'hand_ik.R' in obj.pose.bones)
skin = next(obj for obj in bpy.context.scene.objects if obj.type == 'MESH'
            and any(modifier.type == 'ARMATURE' and modifier.object == rig for modifier in obj.modifiers))
if arguments.skin_mhmat:
    services = services or load_mpfb()
    makeskin = importlib.import_module(services.__package__.rsplit('.', 1)[0]
                                     + '.entities.material.makeskinmaterial')
    definition = makeskin.MakeSkinMaterial()
    definition.populate_from_mhmat(str(arguments.skin_mhmat.resolve()))
    skin_material = bpy.data.materials.new('MPFB adult female skin')
    definition.apply_node_tree(skin_material)
    skin.data.materials.clear()
    skin.data.materials.append(skin_material)
    definition.ensure_uvmap_node_for_texture_nodes(skin)
    # Use MPFB's own nail mask to retain a smoother nail surface in the close-up.
    nodes, links = skin_material.node_tree.nodes, skin_material.node_tree.links
    shader = nodes.get('Principled BSDF')
    nail_mask = nodes.new('ShaderNodeTexImage')
    nail_mask.name = 'MPFB fingernail mask'
    nail_mask.image = bpy.data.images.load(str(arguments.mpfb_dir / 'data/textures/mpfb_fingernails.jpg'), check_existing=True)
    nail_mask.image.colorspace_settings.name = 'Non-Color'
    roughness = nodes.new('ShaderNodeMapRange')
    roughness.inputs['From Min'].default_value = 0
    roughness.inputs['From Max'].default_value = 1
    roughness.inputs['To Min'].default_value = .48
    roughness.inputs['To Max'].default_value = .22
    links.new(nail_mask.outputs['Color'], roughness.inputs['Value'])
    links.new(roughness.outputs['Result'], shader.inputs['Roughness'])
constraint_report = None
if arguments.constraints:
    from tools.preview_constraints import apply_reference
    constraint_report = apply_reference(rig, arguments.constraints)
for obj in bpy.context.scene.objects:
    obj.hide_render = True

addon.register()
addon.HandCalibration(bpy.context, rig, 'R', skin).capture()
control = rig.pose.bones['hand_ik.R']
shoulder = rig.pose.bones['ORG-upper_arm.R'].head
pose = control.matrix.copy()
pose.translation += (shoulder - pose.translation).normalized() * .1
control.matrix = pose
rig.pose.bones['upper_arm_parent.R']['IK_FK'] = 0.0
rig.update_tag()
bpy.context.view_layer.update()
solver = addon.retrieve_snap_solver(bpy.context, rig, 'R')
palm = solver.retrieve_hand_pose() @ solver.wrist.inverted()
across, heading, normal = (palm.to_3x3().col[index].normalized() for index in range(3))

bpy.ops.mesh.primitive_cube_add(size=1)
surface = bpy.context.object
surface.name = 'Preview contact surface'
surface.matrix_world = palm.copy()
surface.location = palm.translation + heading * .06 - normal * .027
surface.scale = (.22, .32, .025)
bpy.ops.object.transform_apply(location=False, rotation=False, scale=True)
bpy.context.view_layer.update()
solver.snap(surface)

# Demonstrate the documented editable-control refinement step. A flat target
# permits more thumb spread than this presentation needs; retain all native
# limits while bringing the thumb toward a relaxed hand pose.
base = rig.pose.bones['thumb.01.R']
tip = rig.pose.bones['thumb.03.R']
thumb_vector = rig.matrix_world.to_3x3() @ (tip.tail - base.head)
thumb_vector -= normal * thumb_vector.dot(normal)
thumb_vector.normalize()
spread_before = math.degrees(math.atan2(abs(thumb_vector.dot(across)), thumb_vector.dot(heading)))
sign = 1 if thumb_vector.dot(across) > 0 else -1
angle = math.radians(arguments.thumb_spread_degrees)
desired = heading * math.cos(angle) + across * sign * math.sin(angle)
turn = math.atan2(normal.dot(thumb_vector.cross(desired)), thumb_vector.dot(desired))
origin = rig.matrix_world @ base.head
change = Matrix.Translation(origin) @ Quaternion(normal, turn).to_matrix().to_4x4() @ Matrix.Translation(-origin)
base.matrix = rig.matrix_world.inverted() @ change @ rig.matrix_world @ base.matrix
rig.update_tag()
bpy.context.view_layer.update()
thumb_vector = rig.matrix_world.to_3x3() @ (tip.tail - base.head)
spread_after = math.degrees(math.atan2(abs(thumb_vector.dot(across)), thumb_vector.dot(heading)))
assert spread_after < spread_before - 10, 'Thumb refinement did not reduce its spread'
if constraint_report:
    from tools.preview_constraints import verify_evaluated_limits
    constraint_report.update(verify_evaluated_limits(rig))

# Extract the evaluated human hand after snapping, including its genuine thumb.
evaluated = skin.evaluated_get(bpy.context.evaluated_depsgraph_get())
mesh = evaluated.to_mesh()
groups = {group.index for group in skin.vertex_groups if group.name.endswith('.R')
          and group.name.startswith(('DEF-hand', 'DEF-palm', 'DEF-f_', 'DEF-thumb'))}
selected = {vertex.index for vertex in mesh.vertices
            if sum(weight.weight for weight in vertex.groups if weight.group in groups) > .2}
faces = [tuple(polygon.vertices) for polygon in mesh.polygons
         if all(index in selected for index in polygon.vertices)]
used = sorted({index for face in faces for index in face})
points = [evaluated.matrix_world @ mesh.vertices[index].co for index in used]
hand_mesh = bpy.data.meshes.new('MPFB evaluated hand')
visible = selected | {vertex.index for vertex in mesh.vertices
                      if (evaluated.matrix_world @ vertex.co - palm.translation).length < .16}
visible_polygons = [polygon for polygon in mesh.polygons
                    if all(index in visible for index in polygon.vertices)]
visible_faces = [tuple(polygon.vertices) for polygon in visible_polygons]
visible_indices = sorted({index for face in visible_faces for index in face})
mapping = {index: offset for offset, index in enumerate(visible_indices)}
hand_mesh.from_pydata([evaluated.matrix_world @ mesh.vertices[index].co for index in visible_indices], [],
                      [tuple(mapping[index] for index in face) for face in visible_faces])
for layer in mesh.uv_layers:
    target = hand_mesh.uv_layers.new(name=layer.name)
    coordinates = [tuple(layer.data[index].uv) for polygon in visible_polygons for index in polygon.loop_indices]
    for loop, uv in zip(target.data, coordinates):
        loop.uv = uv
evaluated.to_mesh_clear()
assert len(points) > 100, 'No usable MPFB hand geometry was extracted'
hand = bpy.data.objects.new('MPFB hand posed by Hand Posing', hand_mesh)
bpy.context.scene.collection.objects.link(hand)
for polygon in hand_mesh.polygons:
    polygon.use_smooth = True
subdivision = hand.modifiers.new('Preview surface smoothing', 'SUBSURF')
subdivision.levels = subdivision.render_levels = 2


def material(name, color, roughness):
    value = bpy.data.materials.new(name)
    shader = value.node_tree.nodes.get('Principled BSDF')
    shader.inputs['Base Color'].default_value = (*color, 1)
    shader.inputs['Roughness'].default_value = roughness
    return value


hand_mesh.materials.append(skin.active_material if arguments.skin_mhmat
                           else material('MPFB hand clay', (.48, .23, .13), .48))
surface.data.materials.append(material('Contact surface', (.08, .19, .24), .6))
bevel = surface.modifiers.new('Soft surface edges', 'BEVEL')
bevel.width, bevel.segments = .003, 3
scene = bpy.context.scene
scene.render.engine = 'CYCLES'
scene.cycles.samples = 64
scene.view_settings.exposure = -1.0
scene.render.resolution_percentage = 100
scene.render.image_settings.file_format = 'PNG'
scene.world = bpy.data.worlds.new('Preview world')
scene.world.use_nodes = True
scene.world.node_tree.nodes['Background'].inputs['Color'].default_value = (.07, .09, .12, 1)
scene.world.node_tree.nodes['Background'].inputs['Strength'].default_value = .5
center = sum(points, Vector()) / len(points)
for offset, energy, size in ((normal * .45 - heading * .25 + across * .15, 35, .4),
                             (normal * .2 + heading * .3 - across * .3, 18, .3)):
    data = bpy.data.lights.new('Preview light', 'AREA')
    data.energy, data.shape, data.size = energy, 'DISK', size
    light = bpy.data.objects.new(data.name, data)
    scene.collection.objects.link(light)
    light.location = center + offset
    light.rotation_euler = (center - light.location).to_track_quat('-Z', 'Y').to_euler()
camera = bpy.data.objects.new('Preview camera', bpy.data.cameras.new('Preview camera'))
scene.collection.objects.link(camera)
camera.data.type = 'ORTHO'
scene.camera = camera


def render(name, offset, square=False):
    scene.render.resolution_x, scene.render.resolution_y = (256, 256) if square else (1920, 1080)
    view = offset.normalized()
    right = heading.cross(view).normalized()
    up = view.cross(right).normalized()
    xs = [(point - center).dot(right) for point in points]
    ys = [(point - center).dot(up) for point in points]
    framed = center + right * ((min(xs) + max(xs)) / 2) + up * ((min(ys) + max(ys)) / 2)
    camera.location = framed + offset
    camera.rotation_euler = Matrix((right, up, view)).transposed().to_euler()
    aspect = scene.render.resolution_x / scene.render.resolution_y
    camera.data.ortho_scale = max(max(xs) - min(xs), (max(ys) - min(ys)) * aspect) * 1.22
    scene.render.filepath = str(project / 'docs' / name)
    bpy.ops.render.render(write_still=True)


if not arguments.skip_render:
    render('preview.png', normal * .45 - heading * .20 + across * .12)
    render('preview-contact.png', normal * .26 + heading * .16 - across * .30)
    render('icon.png', normal * .5 - heading * .05, square=True)
report = {'model': 'Adult female MPFB core basemesh', 'asset_license': 'CC0-1.0',
          'side': 'R', 'rendered_hand_vertices': len(points),
          'source': 'https://static.makehumancommunity.org/mpfb/faq/why_use.html',
          'blender': bpy.app.version_string, 'addon_version': addon.__version__}
report['thumb_refinement'] = {'manual_control_refinement': True, 'spread_before_degrees': spread_before,
                              'spread_after_degrees': spread_after}
if arguments.skin_mhmat:
    report['skin'] = {'material': arguments.skin_mhmat.name,
                      'mhmat_sha256': hashlib.sha256(arguments.skin_mhmat.read_bytes()).hexdigest(),
                      'shader': 'MPFB MakeSkin material with female diffuse texture and fingernail roughness mask',
                      'asset_license': 'CC0-1.0'}
if constraint_report:
    report['joint_limits'] = constraint_report
(project / 'docs/preview-provenance.json').write_text(json.dumps(report, indent=2) + '\n', newline='\n')
print('MPFB preview verified:', {key: value for key, value in report.items() if key != 'joint_limits'})
if constraint_report:
    print('Native limits:', constraint_report['native_limit_constraints'],
          constraint_report['maximum_limit_error_radians'])
